# TRICK: fullwidth substitution - replace ASCII alphanumerics with lookalike fullwidth Unicode
def trick(df, schema, rng, p):
    # Build mapping for ASCII alphanumerics to fullwidth equivalents
    fw_map = {}
    for i in range(10):
        fw_map[chr(ord('0') + i)] = chr(0xFF10 + i)          # ０-９
    for i in range(26):
        fw_map[chr(ord('A') + i)] = chr(0xFF21 + i)          # ＦＵＬＬＷＩＤＴ　Ａ-Ｚ
        fw_map[chr(ord('a') + i)] = chr(0xFF41 + i)          # ＦＵＬＬＷＩＤＴ　ａ-ｚ
    # Optional: also map common punctuation that may appear in ids/decimals
    fw_map['.'] = chr(0xFF0E)                                # 全角句点
    fw_map['-'] = chr(0xFF0D)                                # 全角ハイフン
    fw_map[' '] = chr(0x3000)                                # 全角スペース (optional)

    def to_fullwidth(s):
        return ''.join(fw_map.get(ch, ch) for ch in s)

    # Apply trick only to columns of type 'id' or 'decimal'
    for col_name, col_type, _ in schema:
        if col_type not in ('id', 'decimal'):
            continue
        if col_name not in df.columns:
            continue
        for row_idx in df.index:
            if rng.random() < p:
                original = df.at[row_idx, col_name]
                df.at[row_idx, col_name] = to_fullwidth(original)
    return df

# TRICK: invisible zero-width space insertion - inserts undetectable Unicode ZWSP into strings
def trick(df, schema, rng, p):
    for col_name, col_type, allowed in schema:
        if col_type in ('id', 'name', 'email', 'phone', 'date', 'money', 'decimal', 'int', 'category'):
            for idx in df.index:
                if rng.random() < p:
                    val = df.at[idx, col_name]
                    if isinstance(val, str) and len(val) > 0:
                        pos = rng.randint(0, len(val))
                        zwsp = '\u200b'  # Zero-width space, invisible in most displays
                        df.at[idx, col_name] = val[:pos] + zwsp + val[pos:]
    return df
